def solve(n, a):
    a_sorted = sorted([(a_i, i + 1) for i, a_i in enumerate(a)], reverse=True)
    talks = []
    for i in range(1, n):
        talks.append((a_sorted[i - 1][1], a_sorted[i][1]))
    return len(talks), talks

def main():
    t = int(input())
    results = []
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        k, talks = solve(n, a)
        results.append(f"{k}\n")
        for talk in talks:
            results.append(f"{talk[0]} {talk[1]}\n")
    print("".join(results))

if __name__ == "__main__":
    main()
